function c(t){if(!t.includes("<")||!t.includes(">"))return null;try{if(t.includes("instagram.com")){const e=t.match(/https?:\/\/(?:www\.)?instagram\.com\/p\/[a-zA-Z0-9_-]+\/?/);if(e)return{url:e[0],title:"Instagram Post",description:"Embedded Instagram post",image:"placeholder:instagram"};const r=t.match(/data-instgrm-permalink="([^"]+)"/);if(r)return{url:r[1],title:"Instagram Post",description:"Embedded Instagram post",image:"placeholder:instagram"}}if(t.includes("youtube.com")||t.includes("youtu.be")){const e=t.match(/(?:youtube\.com\/embed\/|youtu\.be\/)([a-zA-Z0-9_-]+)/);if(e){const r=e[1];return{url:`https://www.youtube.com/watch?v=${r}`,title:"YouTube Video",description:"Embedded YouTube video",image:`https://img.youtube.com/vi/${r}/maxresdefault.jpg`}}}if(t.includes("twitter.com")||t.includes("x.com")){const e=t.match(/https?:\/\/(?:twitter|x)\.com\/[^/]+\/status\/\d+/);if(e)return{url:e[0],title:"Twitter/X Post",description:"Embedded Twitter post",image:"placeholder:twitter"}}const o=t.match(/src="([^"]+)"/);return o?{url:o[1],title:"Embedded Content",description:"Embedded media content"}:null}catch(o){return console.error("Error parsing embed code:",o),null}}export{c as parseEmbedCode};
